/**
 * Admin-gated soft-delete for honouring a manual GDPR right-to-
erasure request. Runs the same cascade as `DELETE /me`:
redacts PII on the `users` row, scrubs free-text payloads,
hard-deletes push tokens + legacy bearer tokens, calls Clerk
`users.deleteUser` (best-effort), and queues the user-facing
confirmation email. The 30-day hard-delete cron then purges
the cascaded rows.

 * @summary GDPR-delete a user (admin-triggered)
 */
export const getDeleteAdminUserUrl = (id: string) => {
  return `/api/admin/users/${id}`;
};

export const deleteAdminUser = async (
  id: string,
  options?: RequestInit,
): Promise<AdminUserDeleteResult> => {
  return customFetch<AdminUserDeleteResult>(getDeleteAdminUserUrl(id), {
    ...options,
    method: "DELETE",
  });
};

